package org.formasaloido;

import java.util.*;

/** Bounded, explicit image reading. Luminosity is never inferred physical depth. */
public final class ImageScan {
 public static final class Raster {
  public final int width,height;private final int[] gray;public final double left,top,scale;
  public Raster(int[] argb,int w,int h){if(w<2||h<2||w>4096||h>4096||argb.length!=w*h)throw new IllegalArgumentException("Imagen no válida");double ratio=Math.min(1,192.0/Math.max(w,h));width=Math.max(2,(int)Math.round(w*ratio));height=Math.max(2,(int)Math.round(h*ratio));gray=new int[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int c=argb[Math.min(h-1,y*h/height)*w+Math.min(w-1,x*w/width)],a=c>>>24,l=(77*(c>>16&255)+150*(c>>8&255)+29*(c&255))>>8;gray[y*width+x]=(l*a+255*(255-a))/255;}scale=Math.min(568.0/width,418.0/height);left=(600-width*scale)/2;top=(450-height*scale)/2;}
  public boolean contains(Geometry.Point p){return p.x>=left&&p.x<left+width*scale&&p.y>=top&&p.y<top+height*scale;}
  public double value(Geometry.Point p,int center,int window,boolean invert){if(!contains(p))return 0;int x=Math.min(width-1,(int)((p.x-left)/scale)),y=Math.min(height-1,(int)((p.y-top)/scale));double v=Math.max(0,Math.min(1,(gray[y*width+x]-(center-Math.max(1,window)/2.0))/Math.max(1,window)));return invert?1-v:v;}
 }
 public static final class Section {public final String name;public final Sound.Program program;Section(String n,Sound.Program p){name=n;program=p;}}
 public final List<Section> sections=new ArrayList<>();
 public ImageScan(Geometry g,Raster raster,Sound.Settings settings,int mode,Geometry.Point origin,int step,int center,int window,boolean invert){
  step=Math.max(16,Math.min(80,step));boolean right=origin.x>=300,bottom=origin.y>=225;int nx=(int)Math.ceil(600.0/step),ny=(int)Math.ceil(450.0/step);
  if(mode==2){int first=(origin.y<225?(origin.x<300?0:1):(origin.x<300?3:2));for(int k=0;k<4;k++){int q=(first+k)%4;double x0=q==1||q==2?300:0,y0=q>=2?225:0;Sound.Program p=new Sound.Program(settings);for(int row=0;row<ny;row++){double y=(row+.5)*450/ny;if(y<y0||y>=y0+225)continue;boolean any=false;for(int col=0;col<nx;col++){double x=(col+.5)*600/nx;if(x<x0||x>=x0+300)continue;add(p,g,raster,new Geometry.Point(x,y),settings,false,center,window,invert,step);any=true;}if(any)p.silence(.12);}sections.add(new Section(new String[]{"Superior izquierdo","Superior derecho","Inferior derecho","Inferior izquierdo"}[q],p));}}
  else{int rows=mode==1?nx:ny,cols=mode==1?ny:nx;int originRow=(int)Math.floor((mode==1?origin.x/600:origin.y/450)*rows);originRow=Math.min(rows-1,Math.max(0,originRow));boolean custom=origin.x!=0&&origin.x!=600&&origin.y!=0&&origin.y!=450;
   for(int i=0;i<rows;i++){int row=custom?(originRow+i)%rows:((mode==1?right:bottom)?rows-1-i:i);Sound.Program p=new Sound.Program(settings);for(int j=0;j<cols;j++){int originCol=Math.min(cols-1,Math.max(0,(int)((mode==1?origin.y/450:origin.x/600)*cols)));int col=custom&&i==0?(originCol+j)%cols:((mode==1?bottom:right)?cols-1-j:j);double x=mode==1?(row+.5)*600/nx:(col+.5)*600/nx,y=mode==1?(col+.5)*450/ny:(row+.5)*450/ny;add(p,g,raster,new Geometry.Point(x,y),settings,mode==3,center,window,invert,step);}sections.add(new Section((mode==1?"Columna ":"Fila ")+(row+1),p));}
  }
 }
 private static void add(Sound.Program p,Geometry g,Raster r,Geometry.Point point,Sound.Settings s,boolean fill,int center,int window,boolean invert,int spacing){boolean inside=true;if(fill){int winding=0;for(Geometry.Shape shape:g.shapes)if(shape.closed&&Geometry.inside(point,shape))winding+=shape.hole?-1:1;inside=winding>0;}double value=r==null?(fill?1:vectorValue(g,point,spacing*.5)):r.value(point,center,window,invert);if(r==null&&invert)value=1-value;if(!inside||r!=null&&!r.contains(point))p.silence(.045*s.speed);else p.sample(point,.045*s.speed,.12+.88*value);}
 private static double vectorValue(Geometry g,Geometry.Point p,double tolerance){for(Geometry.Shape shape:g.shapes){if(shape.closed&&Geometry.inside(p,shape))return 1;List<Geometry.Point> points=shape.points;if(points.size()==1&&p.distance(points.get(0))<=tolerance)return 1;for(int i=1;i<points.size();i++)if(Geometry.segmentDistance(p,points.get(i-1),points.get(i))<=tolerance)return 1;}return 0;}
 public Sound.Program program(Sound.Settings settings,int selected){Sound.Program out=new Sound.Program(settings);int first=selected<0?0:selected,last=selected<0?sections.size():selected+1;if(first<0||last>sections.size())throw new IllegalArgumentException("Sección inexistente");for(int n=first;n<last;n++){Sound.Program part=sections.get(n).program;out.pulse(new Geometry.Point(300,225),900,.055,"scan").silence(.12);out.append(part);out.silence(.2);if(out.duration>180)break;}return out.limited(180);}
 public static Sound.Program contour(Geometry g,Sound.Settings s,Geometry.Point origin){Sound.Program out=new Sound.Program(s);List<Geometry.Shape> shapes=new ArrayList<>(g.shapes);shapes.sort(Comparator.comparingDouble(a->nearest(a,origin)));for(Geometry.Shape shape:shapes){List<Geometry.Point> p=new ArrayList<>(shape.points);if(shape.closed){int best=0;for(int i=1;i<p.size();i++)if(p.get(i).distance(origin)<p.get(best).distance(origin))best=i;Collections.rotate(p,-best);p.add(p.get(0));}else if(p.get(p.size()-1).distance(origin)<p.get(0).distance(origin))Collections.reverse(p);if(p.size()==1)out.pulse(p.get(0),0,.3,"vertex");else out.path(p,shape.curve,shape.closed);out.silence(.25);if(out.duration>180)break;}return out.limited(180);}
 private static double nearest(Geometry.Shape s,Geometry.Point p){double d=Double.POSITIVE_INFINITY;for(Geometry.Point q:s.points)d=Math.min(d,p.distance(q));return d;}
}
